sys_script_include.script:
var PlacementStatisticsService = Class.create();

PlacementStatisticsService.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor,
    {

        getCount: function() {

            var driveSysId = this.getParameter('sysparm_drive');
            var status = this.getParameter('sysparm_status');

            if (!driveSysId || !status) {
                return '0';
            }

            var gr = new GlideAggregate(
                'x_snc_college_pl_0_application'
            );

            gr.addQuery('drive', driveSysId);
            gr.addQuery('status', status);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return gr.getAggregate('COUNT');
            }

            return '0';
        },

        type: 'PlacementStatisticsService'
    }
);
